# 갈림길 추가 1~15
JS = r'''
    {id:'x01',f:()=>{ const w=W(); return {txt:⟦교전의 여파로 강 위 다리에 금이 갔다. 다리 위에는 퇴근길 차들이 멈춰 서 있다.¦The aftershock of a battle has cracked the bridge over the river. Evening commuters sit stalled on top of it.¦戦いの余波で川に架かる橋にひびが入った。橋の上には帰宅途中の車が止まっている。¦交战的余波让河上的桥裂开了。桥上停着下班回家的车流。¦交戰的餘波讓河上的橋裂開了。橋上停著下班回家的車流。⟧,ch:[
      {t:⟦서번트에게 다리를 붙잡게 한다¦Have your Servant hold the bridge up¦サーヴァントに橋を支えさせる¦让从者撑住桥¦讓從者撐住橋⟧,r:{연민:5,명예:4,야망:-3},al:{선:5,악:-3},tg:'구조',f:()=>{ w.sm=clamp(w.sm-15); xExp(10); lean('judge',1); return ⟦차들이 다 빠져나갈 때까지 서번트는 한 번도 손을 놓지 않았다. 다음 날 아침, 흔들린 영상 몇 개가 돌았다.¦Your Servant did not let go once until every car was off. By morning, a few shaky videos were going around.¦最後の車が抜けるまで、サーヴァントは一度も手を離さなかった。翌朝、ぶれた動画がいくつか出回った。¦直到最后一辆车驶离，从者一次也没有松手。第二天早上，几段晃动的视频开始流传。¦直到最後一輛車駛離，從者一次也沒有鬆手。第二天早上，幾段晃動的影片開始流傳。⟧; }},
      {t:⟦결계로 통행만 막고 떠난다¦Seal off the bridge with a bounded field and leave¦結界で通行だけ止めて立ち去る¦用结界封住通行后离开¦用結界封住通行後離開⟧,r:{충성:3,명예:1,자유:-1},al:{질서:4},f:()=>⟦사람들은 영문도 모른 채 차를 돌렸다. 다리는 그날 밤 무너졌다.¦People turned their cars around without knowing why. The bridge collapsed that night.¦人々はわけもわからず車を引き返した。橋はその夜に崩れた。¦人们莫名其妙地掉转了车头。那天夜里，桥塌了。¦人們莫名其妙地掉轉了車頭。那天夜裡，橋塌了。⟧},
      {t:⟦혼란을 틈타 달아난 조를 쫓는다¦Use the chaos to chase the team that fled¦混乱に乗じて逃げた陣営を追う¦趁乱追击逃走的那组¦趁亂追擊逃走的那組⟧,r:{야망:5,연민:-5,명예:-2},al:{악:3,선:-5},tg:'-구조',f:()=>{ const t=crossFoe(); if(t) addIntel(t,25,'trail'); lean('judge',-1); return ⟦등 뒤에서 비명과 경적이 뒤엉켰다. 돌아보지 않았다.¦Screams and horns tangled behind you. You did not look back.¦背後で悲鳴とクラクションが入り混じった。振り返らなかった。¦身后尖叫声和喇叭声混成一片。你没有回头。¦身後尖叫聲和喇叭聲混成一片。你沒有回頭。⟧; }}]}; }},
    {id:'x02',f:()=>{ const w=W(); return {txt:⟦근처 병원의 불이 나갔다. 누군가의 결계가 도시의 전력을 빨아들이고 있다.¦The lights have gone out at a nearby hospital. Someone's bounded field is draining the city's power.¦近くの病院の明かりが消えた。誰かの結界が街の電力を吸い上げている。¦附近医院的灯灭了。有人的结界正在吸走城市的电力。¦附近醫院的燈滅了。有人的結界正在吸走城市的電力。⟧,ch:[
      ...(xMage()?[{t:⟦내 마력으로 발전기를 돌린다¦Run the generator on your own mana¦自分の魔力で発電機を回す¦用自己的魔力带动发电机¦用自己的魔力帶動發電機⟧,r:{연민:6,명예:2,야망:-3},al:{선:5},tg:'구조',f:()=>{ add({health:-7}); lean('judge',1); return ⟦새벽까지 발전기 옆에 앉아 있었다. 손끝이 하얗게 식었지만 수술실의 불은 꺼지지 않았다.¦You sat by the generator until dawn. Your fingertips went cold and white, but the operating room never went dark.¦明け方まで発電機のそばに座っていた。指先は白く冷えたが、手術室の明かりは消えなかった。¦你在发电机旁坐到天亮。指尖冷得发白，但手术室的灯没有熄灭。¦你在發電機旁坐到天亮。指尖冷得發白，但手術室的燈沒有熄滅。⟧; }}]:[{t:⟦발전기 연료를 구해 온다¦Go and get fuel for the generator¦発電機の燃料を調達してくる¦去弄来发电机的燃料¦去弄來發電機的燃料⟧,r:{연민:5,명예:2,야망:-2},al:{선:4},tg:'구조',f:()=>{ add({wealth:-8}); lean('judge',1); return ⟦연료통을 몇 번이나 날랐다. 비상등이 다시 켜졌다.¦You hauled fuel cans back and forth. The emergency lights came back on.¦燃料缶を何度も運んだ。非常灯がまた灯った。¦你来回搬了好几趟油桶。应急灯重新亮了。¦你來回搬了好幾趟油桶。應急燈重新亮了。⟧; }}]),
      {t:⟦결계의 주인을 찾아 부순다¦Find whoever set the field and break it¦結界の主を探して壊す¦找到结界的主人并摧毁它¦找到結界的主人並摧毀它⟧,r:{명예:4,야망:3,자유:1},al:{선:2},tg:'정면승부',f:()=>{ const t=crossFoe(); if(t){ addIntel(t,20,'trace'); t.provoked=2; } return ⟦술식의 기점을 셋 부쉈다. 어디선가 이쪽을 노려보는 기척이 남았다.¦You broke three anchors of the spell. Somewhere, a presence was left glaring your way.¦術式の基点を三つ壊した。どこかからこちらを睨む気配が残った。¦你毁掉了三处术式的基点。某处留下了一道盯着你的气息。¦你毀掉了三處術式的基點。某處留下了一道盯著你的氣息。⟧; }},
      {t:⟦모른 척한다¦Pretend you never noticed¦知らないふりをする¦装作不知道¦裝作不知道⟧,r:{연민:-5,명예:-2,야망:2},al:{선:-4},tg:'-구조',f:()=>{ lean('judge',-1); return ⟦그날 밤 뉴스는 보지 않았다.¦You did not watch the news that night.¦その夜はニュースを見なかった。¦那天晚上你没有看新闻。¦那天晚上你沒有看新聞。⟧; }}]}; }},
    {id:'x03',f:()=>{ const w=W(); return {txt:⟦‘성배의 계시’를 받았다는 남자가 광장에 사람들을 모으고 있다. 그 말의 몇 마디는 진짜다.¦A man who claims to have received a revelation from the Grail is gathering people in the square. A few of his words are true.¦「聖杯の啓示」を受けたという男が広場に人を集めている。その言葉のいくつかは本当だ。¦一个自称得到“圣杯启示”的男人正在广场上聚集人群。他说的话里有几句是真的。¦一個自稱得到「聖杯啟示」的男人正在廣場上聚集人群。他說的話裡有幾句是真的。⟧,ch:[
      ...(O().church?[{t:⟦아버지의 교회에 알린다¦Report it to your father's church¦父の教会に知らせる¦通知父亲的教会¦通知父親的教會⟧,r:{명예:3,충성:3},al:{질서:5},tg:'규율',f:()=>{ w.supCold=false; return ⟦다음 날 광장은 비어 있었다. 아버지는 전화로 짧게 고맙다고 했다.¦The next day the square was empty. Your father thanked you briefly over the phone.¦翌日、広場は空になっていた。父は電話で短く礼を言った。¦第二天广场空了。父亲在电话里简短地道了谢。¦第二天廣場空了。父親在電話裡簡短地道了謝。⟧; }}]:[{t:⟦사람들을 흩어 놓는다¦Break up the crowd¦人々を散らす¦驱散人群¦驅散人群⟧,r:{명예:4,충성:1,자유:-1},al:{질서:5},tg:'규율',f:()=>{ xExp(5); return ⟦가벼운 암시와 소란 몇 번으로 모임은 흩어졌다. 남자는 끝까지 하늘을 가리키고 있었다.¦A little suggestion and some commotion broke up the gathering. The man kept pointing at the sky to the end.¦軽い暗示と少しの騒ぎで集まりは散った。男は最後まで空を指さしていた。¦一点暗示加上几次骚动，聚会就散了。那个男人直到最后都指着天空。¦一點暗示加上幾次騷動，聚會就散了。那個男人直到最後都指著天空。⟧; }}]),
      {t:⟦신도들을 정보원으로 쓴다¦Use the believers as informants¦信者たちを情報源に使う¦把信徒当成线人¦把信徒當成線人⟧,r:{야망:5,연민:-4,명예:-3},al:{악:4,선:-4},tg:'계략',f:()=>{ const t=crossFoe(); if(t) addIntel(t,25,'watch'); lean('cruel',1); return ⟦그들은 ‘계시’를 위해 밤새 거리를 헤맸다. 돌아온 쪽지 몇 장은 쓸모가 있었다.¦They roamed the streets all night for their 'revelation.' A few of the notes they brought back were useful.¦彼らは「啓示」のために夜通し街をさまよった。持ち帰ったメモのいくつかは役に立った。¦他们为了“启示”在街上游荡了一整夜。带回来的几张纸条有些用处。¦他們為了「啟示」在街上遊蕩了一整夜。帶回來的幾張紙條有些用處。⟧; }},
      {t:⟦그냥 둔다¦Leave them be¦放っておく¦随他们去¦隨他們去⟧,r:{자유:4,명예:-1},al:{혼돈:3},f:()=>⟦모임은 다음 날에도, 그다음 날에도 열렸다.¦The gathering met again the next day, and the day after.¦集まりは翌日も、その次の日も開かれた。¦聚会第二天、第三天照样举行。¦聚會第二天、第三天照樣舉行。⟧}]}; }},
    {id:'x04',f:()=>{ const w=W(); const can=xMage()||!!O().exorcist; return {txt:⟦귀갓길 골목에서 교복 입은 학생이 불량배들에게 둘러싸여 있다.¦In an alley on the way home, a student in uniform is surrounded by thugs.¦帰り道の路地で、制服姿の学生が不良たちに囲まれている。¦回家路上的小巷里，一个穿校服的学生被小混混围住了。¦回家路上的小巷裡，一個穿校服的學生被小混混圍住了。⟧,ch:[
      {t:⟦서번트가 나선다¦Let your Servant step in¦サーヴァントが出る¦让从者出面¦讓從者出面⟧,r:{연민:5,명예:4,야망:-2},al:{선:5,악:-3},tg:'구조',f:()=>{ xExp(8); lean('judge',1); return ⟦불량배들은 서번트의 그림자만 보고도 흩어졌다. 학생은 인사도 잊고 달려갔다.¦The thugs scattered at the mere shadow of your Servant. The student ran off without even saying thanks.¦不良たちはサーヴァントの影を見ただけで散った。学生は礼も忘れて走り去った。¦小混混们一看到从者的影子就散了。学生连谢都忘了说就跑开了。¦小混混們一看到從者的影子就散了。學生連謝都忘了說就跑開了。⟧; }},
      ...(can?[{t:⟦마스터가 마술로 쫓아낸다¦Drive them off with your own magecraft¦マスターが魔術で追い払う¦御主用魔术把他们赶走¦御主用魔術把他們趕走⟧,r:{연민:4,충성:2},al:{선:4},tg:'구조',f:()=>{ add({will:-2}); lean('judge',1); return ⟦한 놈의 다리가 꼬이고, 다른 놈의 라이터가 터졌다. 골목은 금세 조용해졌다.¦One tripped over his own feet; another's lighter burst. The alley went quiet in no time.¦一人の足がもつれ、もう一人のライターが弾けた。路地はすぐに静かになった。¦一个人脚下一绊，另一个人的打火机炸开了。小巷很快安静下来。¦一個人腳下一絆，另一個人的打火機炸開了。小巷很快安靜下來。⟧; }}]:[{t:⟦직접 막아선다¦Stand in their way yourself¦自分で立ちはだかる¦亲自挡上去¦親自擋上去⟧,r:{연민:4,명예:3,충성:1},al:{선:4},tg:'구조',f:()=>{ add({health:-6}); lean('judge',1); return ⟦한 대 맞았다. 그래도 학생은 그 틈에 빠져나갔다.¦You took a hit. Still, the student slipped away in the meantime.¦一発殴られた。それでも学生はその隙に逃げ出した。¦你挨了一拳。不过学生趁机脱身了。¦你挨了一拳。不過學生趁機脫身了。⟧; }}]),
      {t:⟦신고만 하고 지나간다¦Just call the police and move on¦通報だけして通り過ぎる¦只报警然后走开¦只報警然後走開⟧,r:{충성:2,자유:-1},al:{질서:4},tg:'규율',f:()=>⟦골목 입구에서 순찰차 불빛이 보였다.¦You saw the lights of a patrol car at the mouth of the alley.¦路地の入口にパトカーの光が見えた。¦巷口闪起了巡逻车的灯光。¦巷口閃起了巡邏車的燈光。⟧}]}; }},
    {id:'x05',c:()=>W().day>=3,f:()=>{ const w=W(); return {txt:⟦‘가스 누출’로 한 구역에 피난 권고가 내려졌다. 감독관의 은폐 작업이다. 아직 남은 사람이 많다.¦An evacuation order has gone out for one district over a 'gas leak.' It is the Overseer's cover-up. Many people are still there.¦「ガス漏れ」で一つの区域に避難勧告が出た。監督役の隠蔽工作だ。まだ多くの人が残っている。¦一片街区以“燃气泄漏”为由发布了疏散通知。这是监督者的掩盖手段。还有很多人没走。¦一片街區以「瓦斯外洩」為由發布了疏散通知。這是監督者的掩蓋手段。還有很多人沒走。⟧,ch:[
      {t:⟦주민들의 피난을 돕는다¦Help the residents evacuate¦住民の避難を手伝う¦帮助居民疏散¦幫助居民疏散⟧,r:{연민:5,명예:3,야망:-2},al:{선:5},tg:'구조',f:()=>{ xExp(6); add({will:2}); return ⟦노인 몇을 업어 날랐다. 마지막 버스가 떠날 때 누군가 창문을 두드려 고개를 숙였다.¦You carried a few old people on your back. As the last bus left, someone tapped on the window and bowed.¦お年寄りを何人か背負って運んだ。最後のバスが出るとき、誰かが窓を叩いて頭を下げた。¦你背着几位老人送上了车。最后一班车开走时，有人敲着车窗向你低头致意。¦你背著幾位老人送上了車。最後一班車開走時，有人敲著車窗向你低頭致意。⟧; }},
      {t:⟦비어 버린 구역의 다른 조 거점을 친다¦Hit another team's base in the emptied district¦空になった区域の他陣営の拠点を叩く¦袭击空出来的街区里别组的据点¦襲擊空出來的街區裡別組的據點⟧,r:{야망:6,명예:-2,연민:-2},al:{악:3,혼돈:2,질서:-2},tg:'계략',f:()=>{ const t=crossFoe(); if(t){ t.hp=clamp(t.hp-12); addIntel(t,15,'trace'); } xExp(8); return ⟦빈 거리에 폭음이 한 번 울렸다. 그 조의 결계가 반쯤 무너졌다.¦A single blast rang through the empty streets. Half of that team's bounded field came down.¦無人の通りに爆音が一度響いた。その陣営の結界は半分崩れた。¦空荡的街道上响起一声爆炸。那组的结界塌了一半。¦空蕩的街道上響起一聲爆炸。那組的結界塌了一半。⟧; }},
      {t:⟦방송에 맞춰 조용히 거처를 옮긴다¦Quietly move your base under cover of the broadcast¦放送に合わせて静かに拠点を移す¦趁着广播悄悄转移据点¦趁著廣播悄悄轉移據點⟧,r:{충성:3,자유:-1},al:{질서:4},tg:'규율',f:()=>{ xExp(-8); return ⟦피난 행렬에 섞여 짐을 옮겼다. 아무도 눈여겨보지 않았다.¦You moved your things mixed in with the evacuees. No one paid any attention.¦避難の列に紛れて荷物を運んだ。誰も気に留めなかった。¦你混在疏散的人群里搬走了东西。没有人留意。¦你混在疏散的人群裡搬走了東西。沒有人留意。⟧; }}]}; }},
    {id:'x06',f:()=>{ const w=W(); return {txt:⟦집을 못 찾는 노인이 서번트의 소매를 붙잡는다. 이 동네에서 오래 살았다고 한다.¦An old man who cannot find his way home grabs your Servant's sleeve. He says he has lived in this neighborhood a long time.¦家がわからなくなった老人が、サーヴァントの袖をつかむ。この町に長く住んでいるという。¦一位找不到家的老人拉住了从者的袖子。他说自己在这一带住了很久。¦一位找不到家的老人拉住了從者的袖子。他說自己在這一帶住了很久。⟧,ch:[
      {t:⟦집을 찾아 준다¦Help him find his home¦家を探してあげる¦帮他找到家¦幫他找到家⟧,r:{연민:5,명예:2,야망:-2},al:{선:4},f:()=>{ add({will:2}); return ⟦반나절을 헤맨 끝에 대문 앞에 섰다. 노인은 서번트에게 사탕 하나를 쥐여 주었다.¦After half a day of wandering you reached his gate. The old man pressed a piece of candy into your Servant's hand.¦半日さまよった末に門の前に着いた。老人はサーヴァントに飴をひとつ握らせた。¦转了半天终于站到了他家门口。老人往从者手里塞了一颗糖。¦轉了半天終於站到了他家門口。老人往從者手裡塞了一顆糖。⟧; }},
      ...(xMage()?[{t:⟦기억을 읽어 동네 소문을 캔다¦Read his memories for neighborhood gossip¦記憶を読んで町の噂を探る¦读取他的记忆打探街坊传闻¦讀取他的記憶打探街坊傳聞⟧,r:{야망:5,연민:-4,명예:-3},al:{악:4,선:-4},tg:'계략',f:()=>{ const t=crossFoe(); if(t) addIntel(t,25,'watch'); lean('judge',-1); return ⟦흐릿한 기억 사이로 밤마다 불이 켜지는 빈집 하나가 보였다.¦Among his blurred memories was an empty house whose lights came on every night.¦ぼやけた記憶の中に、毎晩明かりの灯る空き家がひとつ見えた。¦在模糊的记忆里，看见了一栋每晚都会亮灯的空房子。¦在模糊的記憶裡，看見了一棟每晚都會亮燈的空房子。⟧; }}]:[{t:⟦노인에게 동네 소문을 캐묻는다¦Press him for neighborhood gossip¦老人に町の噂を問いただす¦向老人打听街坊传闻¦向老人打聽街坊傳聞⟧,r:{야망:4,연민:-3},al:{악:2,선:-2},tg:'계략',f:()=>{ const t=crossFoe(); if(t) addIntel(t,15,'talk'); return ⟦노인은 묻지 않은 것까지 이야기했다. 그중 하나가 쓸 만했다.¦He told you things you hadn't even asked about. One of them was useful.¦老人は聞いていないことまで話した。そのひとつが使えた。¦老人连没问的事都说了。其中有一件派得上用场。¦老人連沒問的事都說了。其中有一件派得上用場。⟧; }}]),
      {t:⟦경찰에 맡긴다¦Leave him with the police¦警察に任せる¦交给警察¦交給警察⟧,r:{충성:2},al:{질서:4},tg:'규율',f:()=>⟦파출소 앞에서 노인은 서번트에게 손을 흔들었다.¦In front of the police box, the old man waved to your Servant.¦交番の前で、老人はサーヴァントに手を振った。¦在派出所门口，老人朝从者挥了挥手。¦在派出所門口，老人朝從者揮了揮手。⟧}]}; }},
    {id:'x07',f:()=>{ const w=W(); return {txt:⟦시내에 등불 축제가 열렸다. 서번트가 걸음을 멈추고 등불 쪽을 보고 있다.¦A lantern festival has opened downtown. Your Servant has stopped walking and is looking toward the lanterns.¦市街で灯籠祭りが開かれた。サーヴァントが足を止めて灯りの方を見ている。¦市区办起了灯会。从者停下脚步，望着灯火那边。¦市區辦起了燈會。從者停下腳步，望著燈火那邊。⟧,ch:[
      {t:⟦서번트와 함께 걷는다¦Walk the festival together¦サーヴァントと一緒に歩く¦和从者一起逛¦和從者一起逛⟧,r:{자유:5,연민:3,야망:-2},al:{혼돈:2},f:()=>{ add({will:3}); xExp(6); return ⟦둘이서 등불 아래를 끝까지 걸었다. 오늘 밤만은 전쟁 이야기를 하지 않았다.¦The two of you walked beneath the lanterns to the very end. Just for tonight, neither of you spoke of the war.¦二人で灯りの下を最後まで歩いた。今夜だけは戦争の話をしなかった。¦你们在灯下一直走到了尽头。只有今晚，谁都没提起战争。¦你們在燈下一直走到了盡頭。只有今晚，誰都沒提起戰爭。⟧; }},
      {t:⟦인파 속에서 다른 조를 살핀다¦Watch for other teams in the crowd¦人混みの中で他陣営を探る¦在人群中观察别的组¦在人群中觀察別的組⟧,r:{야망:4,충성:2,자유:-2},f:()=>{ const t=crossFoe(); if(t) addIntel(t,20,'watch'); return ⟦등불 아래 낯익은 기척 하나가 스쳐 지나갔다.¦A familiar presence brushed past under the lanterns.¦灯りの下で見覚えのある気配がひとつすれ違った。¦灯下有一道熟悉的气息擦身而过。¦燈下有一道熟悉的氣息擦身而過。⟧; }},
      {t:⟦사람 많은 곳은 피한다¦Stay away from the crowds¦人の多い所は避ける¦避开人多的地方¦避開人多的地方⟧,r:{자유:-4,충성:2,야망:1},al:{질서:3},tg:'규율',f:()=>{ xExp(-5); return ⟦서번트는 한 번 뒤를 돌아보고 따라왔다.¦Your Servant looked back once, then followed.¦サーヴァントは一度だけ振り返ってからついてきた。¦从者回头看了一眼，然后跟了上来。¦從者回頭看了一眼，然後跟了上來。⟧; }}]}; }},
    {id:'x08',fight:true,c:()=>xFoes().length>0,f:()=>{ const w=W(), p=pick(xFoes()); return {txt:⟦다른 조가 민간인 하나를 앞세운 채 길을 막아섰다. 비키지 않으면 그 사람이 다친다.¦Another team has blocked the road, holding a civilian in front of them. If you don't step aside, that person gets hurt.¦他陣営が民間人を盾にして道をふさいだ。どかなければその人が傷つく。¦另一组挟持着一个平民挡住了去路。不让开的话，那个人就会受伤。¦另一組挾持著一個平民擋住了去路。不讓開的話，那個人就會受傷。⟧,ch:[
      {t:⟦정면으로 구해 낸다¦Rescue them head-on¦正面から救い出す¦正面把人救出来¦正面把人救出來⟧,r:{명예:5,연민:4,야망:-2},al:{선:5,악:-3},tg:['정면승부','구조'],f:()=>{ w.hp=clamp(w.hp-10); p.hp=clamp(p.hp-8); p.provoked=2; xFight(); lean('judge',1); return ⟦서번트가 한 걸음에 거리를 좁혔다. 인질은 무사했고, 그 조는 이를 갈며 물러났다.¦Your Servant closed the distance in a single step. The hostage was safe, and the team withdrew gnashing their teeth.¦サーヴァントが一歩で間合いを詰めた。人質は無事で、その陣営は歯噛みして退いた。¦从者一步就拉近了距离。人质平安无事，那组咬牙切齿地退走了。¦從者一步就拉近了距離。人質平安無事，那組咬牙切齒地退走了。⟧; }},
      {t:⟦말로 풀어 본다¦Try to talk it out¦話し合ってみる¦试着用话语化解¦試著用話語化解⟧,r:{연민:5,명예:1,야망:-2},al:{선:3},f:()=>{ if(ch(.5)){ p.friendly=true; return ⟦긴 대화 끝에 인질이 풀려났다. 그 조의 마스터는 이쪽을 다시 보았다.¦After a long talk, the hostage was released. That team's Master looked at you again.¦長い話し合いの末に人質は解放された。その陣営のマスターはこちらを見直した。¦一番长谈之后，人质被放了。那组的御主重新打量了你。¦一番長談之後，人質被放了。那組的御主重新打量了你。⟧; } w.hp=clamp(w.hp-8); xFight(); return ⟦말이 끝나기도 전에 공격이 날아왔다. 인질은 구했지만 서번트가 다쳤다.¦An attack came before you finished speaking. You saved the hostage, but your Servant was hurt.¦言い終わる前に攻撃が飛んできた。人質は助けたがサーヴァントが傷を負った。¦话还没说完攻击就来了。人质救下了，从者却受了伤。¦話還沒說完攻擊就來了。人質救下了，從者卻受了傷。⟧; }},
      {t:⟦그 틈에 마스터를 노린다¦Go for their Master while they're distracted¦その隙にマスターを狙う¦趁机狙击对方御主¦趁機狙擊對方御主⟧,r:{야망:6,연민:-6,명예:-4},al:{악:5,선:-6},tg:'무자비',f:()=>{ p.mHurt=3; lean('cruel',1); return ⟦그 조의 마스터가 피를 흘리며 쓰러졌다. 인질이 어떻게 됐는지는 끝내 보지 못했다.¦That team's Master fell, bleeding. You never did see what became of the hostage.¦その陣営のマスターが血を流して倒れた。人質がどうなったのかは、ついに見なかった。¦那组的御主流着血倒下了。人质后来怎么样了，你始终没有去看。¦那組的御主流著血倒下了。人質後來怎麼樣了，你始終沒有去看。⟧; }}]}; }},
    {id:'x09',f:()=>{ const w=W(); return {txt:⟦폐건물에 사는 사람들 곁에 누군가의 공방이 들어섰다. 사람을 재료로 쓸 모양이다.¦Someone has set up a workshop next to the people living in an abandoned building. It looks like they mean to use people as material.¦廃ビルで暮らす人々のそばに、誰かの工房ができた。人を材料にするつもりらしい。¦在废楼里栖身的人们旁边，有人建起了工房。看样子是要拿人当材料。¦在廢樓裡棲身的人們旁邊，有人建起了工房。看樣子是要拿人當材料。⟧,ch:[
      {t:⟦공방을 막아선다¦Stand against the workshop¦工房に立ちはだかる¦阻止那座工房¦阻止那座工房⟧,r:{연민:5,명예:4,야망:-2},al:{선:6,악:-4},tg:'구조',f:()=>{ const t=crossFoe(); if(t){ t.provoked=2; addIntel(t,15,'trace'); } lean('judge',1); return ⟦공방의 술식을 뜯어냈다. 사람들은 무슨 일이 있었는지도 모른 채 잠들어 있었다.¦You tore out the workshop's spellwork. The people slept on, never knowing what had happened.¦工房の術式を引き剥がした。人々は何があったかも知らずに眠っていた。¦你拆掉了工房的术式。那些人一无所知地睡着。¦你拆掉了工房的術式。那些人一無所知地睡著。⟧; }},
      {t:⟦사람들을 데려와 숨긴다¦Take the people somewhere safe¦人々を連れ出してかくまう¦把人们带走藏起来¦把人們帶走藏起來⟧,r:{연민:6,명예:1,야망:-2},al:{선:5},tg:'구조',f:()=>{ add({wealth:-8}); return ⟦여관 방 몇 개를 빌렸다. 누군가 오랜만에 따뜻한 물로 씻는다고 했다.¦You rented a few rooms at an inn. Someone said it was the first warm bath they'd had in ages.¦宿の部屋をいくつか借りた。誰かが久しぶりに温かい湯で洗えると言った。¦你租了几间旅馆的房间。有人说好久没用热水洗过澡了。¦你租了幾間旅館的房間。有人說好久沒用熱水洗過澡了。⟧; }},
      {t:⟦공방 위치만 기억해 둔다¦Just remember where the workshop is¦工房の場所だけ覚えておく¦只记下工房的位置¦只記下工房的位置⟧,r:{야망:4,연민:-4},al:{악:2,선:-3},tg:['계략','-구조'],f:()=>{ const t=crossFoe(); if(t) addIntel(t,25,'trace'); lean('judge',-1); return ⟦지도에 표시 하나를 더했다. 그 건물의 불빛은 다음 주에 꺼졌다.¦You added one more mark to the map. The lights in that building went out the following week.¦地図に印をひとつ足した。その建物の明かりは翌週消えた。¦你在地图上多画了一个记号。那栋楼的灯光在下周熄灭了。¦你在地圖上多畫了一個記號。那棟樓的燈光在下週熄滅了。⟧; }}]}; }},
    {id:'x10',c:()=>xMage()&&S.wealth>=35,f:()=>{ const w=W(); return {txt:⟦마술사들이 드나드는 지하 도박장에서 판돈으로 ‘성유물 조각’이 걸렸다.¦At an underground gambling den frequented by mages, a 'fragment of a holy relic' has been put up as the stake.¦魔術師が出入りする地下賭場で、賭け金に「聖遺物のかけら」が出された。¦在魔术师出入的地下赌场里，“圣遗物碎片”被押作了赌注。¦在魔術師出入的地下賭場裡，「聖遺物碎片」被押作了賭注。⟧,ch:[
      {t:⟦판에 앉는다¦Take a seat at the table¦卓につく¦坐上赌桌¦坐上賭桌⟧,r:{야망:4,자유:4,충성:-1},al:{혼돈:4,질서:-2},f:()=>{ if(ch(.5)){ add({wealth:12}); w.sm=clamp(w.sm+10); return ⟦마지막 패가 뒤집혔다. 조각은 이쪽 손에 남았다.¦The last card turned over. The fragment stayed in your hand.¦最後の札がめくられた。かけらはこちらの手に残った。¦最后一张牌翻开了。碎片留在了你手里。¦最後一張牌翻開了。碎片留在了你手裡。⟧; } add({wealth:-12}); return ⟦지갑이 가벼워졌다. 상대는 조각을 들고 웃으며 사라졌다.¦Your wallet got lighter. Your opponent walked off with the fragment, smiling.¦財布が軽くなった。相手はかけらを手に笑って消えた。¦钱包变轻了。对方拿着碎片笑着走了。¦錢包變輕了。對方拿著碎片笑著走了。⟧; }},
      {t:⟦판을 엎는다¦Flip the table¦卓をひっくり返す¦掀翻赌桌¦掀翻賭桌⟧,r:{명예:4,야망:-1,자유:1},al:{질서:3},tg:'정면승부',f:()=>{ xExp(8); return ⟦조각은 누구의 것도 되지 않고 깨졌다. 그 도박장은 다음 날 문을 닫았다.¦The fragment broke and became no one's. The den closed the next day.¦かけらは誰のものにもならずに砕けた。その賭場は翌日店を閉めた。¦碎片碎了，谁也没得到。那家赌场第二天就关门了。¦碎片碎了，誰也沒得到。那家賭場第二天就關門了。⟧; }},
      {t:⟦장부를 몰래 훔쳐본다¦Sneak a look at the ledger¦帳簿を盗み見る¦偷看账本¦偷看帳本⟧,r:{야망:3,명예:-2},al:{악:1},tg:'계략',f:()=>{ const t=crossFoe(); if(t) addIntel(t,20,'trace'); return ⟦장부에 낯익은 이름이 적혀 있었다. 큰돈을 잃은 다른 조의 마스터였다.¦A familiar name was in the ledger. Another team's Master, who had lost a lot of money.¦帳簿に見覚えのある名前があった。大金をすった他陣営のマスターだ。¦账本上有个熟悉的名字。是输了大钱的另一组御主。¦帳本上有個熟悉的名字。是輸了大錢的另一組御主。⟧; }}]}; }},
    {id:'x11',c:()=>W().pairs.some(p=>p.fought),f:()=>{ const w=W(); return {txt:⟦어젯밤 교전이 번져 아파트에 불이 붙었다. 안에 아직 사람이 남아 있다.¦Last night's fighting spread and set an apartment building on fire. There are still people inside.¦昨夜の戦いが燃え広がり、アパートに火がついた。中にまだ人が残っている。¦昨夜的交战蔓延开来，一栋公寓起了火。里面还有人。¦昨夜的交戰蔓延開來，一棟公寓起了火。裡面還有人。⟧,ch:[
      {t:⟦서번트를 불 속으로 보낸다¦Send your Servant into the fire¦サーヴァントを火の中へ送る¦让从者冲进火里¦讓從者衝進火裡⟧,r:{연민:5,명예:4,야망:-2},al:{선:6,악:-3},tg:'구조',f:()=>{ w.hp=clamp(w.hp-10); xExp(10); lean('judge',1); return ⟦서번트가 연기 속에서 아이 둘을 데리고 나왔다. 머리카락 끝이 그을려 있었다.¦Your Servant came out of the smoke with two children. The tips of their hair were singed.¦サーヴァントが煙の中から子どもを二人連れて出てきた。髪の先が焦げていた。¦从者带着两个孩子从浓烟里走了出来。发梢被烧焦了。¦從者帶著兩個孩子從濃煙裡走了出來。髮梢被燒焦了。⟧; }},
      {t:⟦소방차 길만 터 준다¦Just clear the way for the fire trucks¦消防車の道だけ開ける¦只为消防车开路¦只為消防車開路⟧,r:{충성:3,연민:1},al:{질서:4},tg:'규율',f:()=>⟦막힌 골목의 차들을 몇 대 밀어냈다. 사이렌이 제때 닿았다.¦You pushed a few cars out of the blocked alley. The sirens arrived in time.¦ふさがった路地の車を何台か押しのけた。サイレンは間に合った。¦你推开了堵在巷子里的几辆车。警笛及时赶到了。¦你推開了堵在巷子裡的幾輛車。警笛及時趕到了。⟧},
      {t:⟦불길에 숨어 지나간다¦Slip past under cover of the flames¦炎に紛れて通り過ぎる¦借着火势悄悄离开¦借著火勢悄悄離開⟧,r:{야망:4,연민:-6,명예:-2},al:{악:3,선:-6},tg:'-구조',f:()=>{ xExp(-6); lean('judge',-1); return ⟦연기가 모든 것을 가려 주었다. 뒤에서 누군가 이름을 불렀다.¦The smoke hid everything. Behind you, someone was calling a name.¦煙がすべてを隠してくれた。背後で誰かが名前を呼んでいた。¦浓烟遮住了一切。身后有人在喊着谁的名字。¦濃煙遮住了一切。身後有人在喊著誰的名字。⟧; }}]}; }},
    {id:'x12',f:()=>{ const w=W(); const can=xMage()||!!O().exorcist; return {txt:⟦옆집 사람이 ‘밤마다 이상한 소리가 난다’며 문을 두드린다.¦Your next-door neighbor knocks on the door, complaining of strange noises every night.¦隣の人が「毎晩変な音がする」とドアを叩く。¦隔壁邻居敲门说“每天晚上都有怪声”。¦隔壁鄰居敲門說「每天晚上都有怪聲」。⟧,ch:[
      {t:⟦얼버무리고 사과한다¦Make excuses and apologize¦ごまかして謝る¦含糊其辞地道歉¦含糊其辭地道歉⟧,r:{충성:2,명예:1},al:{질서:3},f:()=>⟦이웃은 미심쩍은 얼굴로 돌아갔다.¦The neighbor went back looking unconvinced.¦隣人は腑に落ちない顔で帰っていった。¦邻居一脸怀疑地回去了。¦鄰居一臉懷疑地回去了。⟧},
      ...(can?[{t:⟦암시로 기억을 흐린다¦Blur their memory with suggestion¦暗示で記憶をぼかす¦用暗示模糊对方的记忆¦用暗示模糊對方的記憶⟧,r:{야망:4,명예:-3,연민:-2},al:{악:3,선:-2},tg:'계략',f:()=>{ xExp(-8); return ⟦이웃은 왜 문을 두드렸는지 잊은 얼굴로 돌아갔다.¦The neighbor left looking as if they had forgotten why they'd knocked.¦隣人はなぜドアを叩いたのか忘れた顔で帰っていった。¦邻居一副忘了自己为什么来敲门的样子回去了。¦鄰居一副忘了自己為什麼來敲門的樣子回去了。⟧; }}]:[{t:⟦돈으로 입을 막는다¦Pay them to keep quiet¦金で口を封じる¦用钱堵住对方的嘴¦用錢堵住對方的嘴⟧,r:{야망:3,명예:-2},al:{악:1},tg:'계략',f:()=>{ add({wealth:-6}); xExp(-6); return ⟦봉투를 받은 이웃은 더는 아무 소리도 듣지 못했다고 했다.¦After taking the envelope, the neighbor said they hadn't heard a thing.¦封筒を受け取った隣人は、もう何も聞こえないと言った。¦收下信封的邻居说，他什么声音都没听到过。¦收下信封的鄰居說，他什麼聲音都沒聽到過。⟧; }}]),
      {t:⟦짐을 싸 거처를 옮긴다¦Pack up and move¦荷物をまとめて拠点を移す¦收拾行李转移据点¦收拾行李轉移據點⟧,r:{자유:4,충성:1},al:{혼돈:2},f:()=>{ w.fort=clamp(w.fort-10); xExp(-10); return ⟦한밤중에 짐을 옮겼다. 새 거처의 결계는 아직 얇다.¦You moved in the dead of night. The bounded field at the new place is still thin.¦夜中に荷物を運んだ。新しい拠点の結界はまだ薄い。¦你半夜搬了家。新据点的结界还很薄。¦你半夜搬了家。新據點的結界還很薄。⟧; }}]}; }},
    {id:'x13',c:()=>W().pairs.some(p=>p.lone&&p.loneD!=null&&W().day-p.loneD<=1),f:()=>{ const w=W(), p=pick(w.pairs.filter(p=>p.lone&&p.loneD!=null&&w.day-p.loneD<=1)); return {txt:⟦쓰러진 적 서번트가 흩어지기 전에 남긴 말이 귀에 남아 있다. 마스터만은 살려 달라고.¦The words of a fallen enemy Servant linger in your ears from just before it faded: spare my Master, at least.¦倒れた敵サーヴァントが消える前に残した言葉が耳に残っている。マスターだけは助けてくれと。¦倒下的敌方从者消散前留下的话还回响在耳边：至少放过我的御主。¦倒下的敵方從者消散前留下的話還迴響在耳邊：至少放過我的御主。⟧,ch:[
      {t:⟦부탁을 들어준다¦Honor the request¦頼みを聞き入れる¦答应它的请求¦答應它的請求⟧,r:{명예:5,연민:4,야망:-3},al:{선:4,질서:3},f:()=>{ p.friendly=true; p.spared=true; addIntel(p,15,'talk'); return ⟦그 마스터는 다음 날 도시를 떠났다. 떠나기 전 짧은 편지 한 장을 남겼다.¦That Master left the city the next day, leaving behind a short letter.¦そのマスターは翌日街を去った。去る前に短い手紙を一通残していった。¦那位御主第二天离开了城市，临走前留下了一封短信。¦那位御主第二天離開了城市，臨走前留下了一封短信。⟧; }},
      {t:⟦거절하고 떠난다¦Refuse and walk away¦断って立ち去る¦拒绝后离开¦拒絕後離開⟧,r:{야망:3,명예:-1},f:()=>⟦약속은 하지 않았다. 그렇다고 칼을 뽑지도 않았다.¦You made no promise. Neither did you draw a blade.¦約束はしなかった。かといって刃も抜かなかった。¦你没有许下承诺，但也没有拔刀。¦你沒有許下承諾，但也沒有拔刀。⟧},
      {t:⟦마스터까지 끝낸다¦Finish off the Master too¦マスターまで仕留める¦连御主一起解决¦連御主一起解決⟧,r:{야망:6,명예:-6,연민:-6},al:{악:5,선:-6},tg:'무자비',f:()=>{ p.lone=false; p.master=false; S.flags.killedMaster=1; if(p.hurtMe) lean('avenger',1); else lean('cruel',1); add({will:-3}); return ⟦재계약의 기회는 오지 않았다. 손등의 피가 오래 식지 않았다.¦No chance at a new contract would come. The blood on your hand took a long time to cool.¦再契約の機会は来なかった。手の甲の血はなかなか冷めなかった。¦再也不会有重新契约的机会了。手背上的血很久都没有变凉。¦再也不會有重新契約的機會了。手背上的血很久都沒有變涼。⟧; }}]}; }},
    {id:'x14',c:()=>W().pairs.some(p=>p.lone),f:()=>{ const w=W(), p=pick(w.pairs.filter(p=>p.lone)); return {txt:⟦서번트를 잃은 마스터가 교회로도 가지 못하고 다리 밑에서 떨고 있다.¦A Master who lost their Servant is shivering under a bridge, unable even to go to the church.¦サーヴァントを失ったマスターが、教会にも行けず橋の下で震えている。¦失去从者的御主连教会都去不了，在桥下发抖。¦失去從者的御主連教會都去不了，在橋下發抖。⟧,ch:[
      {t:⟦거둬 준다¦Take them in¦かくまってやる¦收留对方¦收留對方⟧,r:{연민:6,명예:2,야망:-2},al:{선:5},tg:'구조',f:()=>{ add({wealth:-6}); addIntel(crossFoe()||p,20,'talk'); lean('judge',1); return ⟦그는 밤새 아무 말도 하지 않다가, 새벽에 다른 조의 이야기를 꺼냈다.¦They said nothing all night, then at dawn began talking about another team.¦その人は一晩中黙っていたが、明け方に他陣営の話を始めた。¦对方整晚一言不发，到了清晨才说起另一组的事。¦對方整晚一言不發，到了清晨才說起另一組的事。⟧; }},
      {t:⟦정보만 받고 돌려보낸다¦Get information and send them off¦情報だけもらって帰す¦拿到情报后打发走¦拿到情報後打發走⟧,r:{야망:5,연민:-3},al:{악:2},tg:'계략',f:()=>{ const t=crossFoe(); if(t) addIntel(t,20,'talk'); return ⟦몇 가지를 들었다. 그는 다시 다리 밑으로 돌아갔다.¦You heard a few things. They went back under the bridge.¦いくつか聞き出した。その人はまた橋の下へ戻っていった。¦你问出了几件事。对方又回到了桥下。¦你問出了幾件事。對方又回到了橋下。⟧; }},
      ...(O().church?[{t:⟦아버지의 교회로 데려간다¦Take them to your father's church¦父の教会へ連れていく¦带对方去父亲的教会¦帶對方去父親的教會⟧,r:{충성:3,연민:3,명예:1},al:{질서:5,선:2},tg:'규율',f:()=>{ w.supCold=false; return ⟦아버지가 문을 열고 말없이 담요를 내밀었다.¦Your father opened the door and silently held out a blanket.¦父が扉を開け、黙って毛布を差し出した。¦父亲打开门，默默地递上了一条毯子。¦父親打開門，默默地遞上了一條毯子。⟧; }}]:[{t:⟦감독관에게 넘긴다¦Hand them over to the Overseer¦監督役に引き渡す¦交给监督者¦交給監督者⟧,r:{충성:4,명예:1,자유:-1},al:{질서:5},tg:'규율',f:()=>{ w.supCold=false; return ⟦감독관은 서류 한 장에 서명을 받고 그를 데려갔다.¦The Overseer had you sign a form and took them away.¦監督役は書類に署名させて、その人を連れていった。¦监督者让你签了一张文件，便把人带走了。¦監督者讓你簽了一張文件，便把人帶走了。⟧; }}])]}; }},
    {id:'x15',fight:true,c:()=>xFoes().length>0,f:()=>{ const w=W(), p=pick(xFoes()); return {txt:⟦다른 조에게서 쪽지가 왔다. 오늘 밤만은 서로 싸우지 말자고 적혀 있다.¦A note has come from another team. It says: let's not fight each other, just for tonight.¦他陣営からメモが届いた。今夜だけは互いに戦わないでおこうと書いてある。¦另一组送来一张纸条，上面写着：只有今晚，我们别打。¦另一組送來一張紙條，上面寫著：只有今晚，我們別打。⟧,ch:[
      {t:⟦받아들인다¦Accept¦受け入れる¦接受¦接受⟧,r:{자유:4,명예:3},al:{혼돈:2},f:()=>{ p.halt=Math.max(p.halt||0,1); addIntel(p,15,'talk'); return ⟦그날 밤 그 조와는 마주치지 않았다. 대신 쪽지 뒷면에 거처 근처의 지명이 하나 적혀 있었다.¦You did not run into that team that night. On the back of the note, though, was the name of a place near their base.¦その夜その陣営とは出くわさなかった。代わりにメモの裏に拠点近くの地名がひとつ書かれていた。¦那晚没有遇上那组。不过纸条背面写着他们据点附近的一个地名。¦那晚沒有遇上那組。不過紙條背面寫著他們據點附近的一個地名。⟧; }},
      {t:⟦거절한다¦Refuse¦断る¦拒绝¦拒絕⟧,r:{충성:3,야망:2},al:{질서:3},f:()=>{ p.provoked=2; return ⟦쪽지를 찢어 돌려보냈다. 답은 그것으로 충분했다.¦You tore the note up and sent it back. That was answer enough.¦メモを破って送り返した。返事はそれで十分だった。¦你把纸条撕了送回去。这就是答复。¦你把紙條撕了送回去。這就是答覆。⟧; }},
      {t:⟦받아들이는 척 뒤를 친다¦Pretend to accept, then strike from behind¦受け入れたふりをして背後を突く¦假装接受，再从背后偷袭¦假裝接受，再從背後偷襲⟧,r:{야망:6,명예:-7,충성:-1},al:{악:4,질서:-5},tg:['계략','-정면승부'],f:()=>{ p.hp=clamp(p.hp-15); xExp(6); xFight(); lean('judge',-1); return ⟦방심한 거처에 불길이 일었다. 그날부터 다른 조들이 이쪽을 보는 눈이 달라졌다.¦Fire rose from the off-guard base. From that day, the other teams looked at you differently.¦油断した拠点に火の手が上がった。その日から他陣営がこちらを見る目が変わった。¦毫无防备的据点燃起了大火。从那天起，其他组看你的眼神变了。¦毫無防備的據點燃起了大火。從那天起，其他組看你的眼神變了。⟧; }}]}; }},
'''
